-- ---------------------------------------------------------------------------
-- Nathrezim Foresight (200507): crit DAMAGE bonus instead of crit CHANCE.
--
-- Effect 2 was SPELL_AURA_MOD_SPELL_CRIT_CHANCE (57), whose MiscValue is
-- unused.  SPELL_AURA_MOD_CRIT_DAMAGE_BONUS (163) is read via
-- GetTotalAuraModifierByMiscMask(..., spellProto->GetSchoolMask())
-- (Unit.cpp:9421), so its MiscValue IS a school mask and must be set to 127
-- (all schools) to match effect 1.  Leaving it at 0 would match no school and
-- the bonus would silently never apply.
--
-- Amount is unchanged: BasePoints2 = 0, DieSides2 = 1 -> 1 per stack.
-- AuraEffect::CalculateAmount does an unconditional
-- `amount *= GetBase()->GetStackAmount()` (SpellAuraEffects.cpp:580), so this
-- scales per Soul Shard exactly as the damage-taken effect already does:
-- 32 shards -> +32% critical strike damage.
-- ---------------------------------------------------------------------------
UPDATE `alonecraft_spell_dbc`
SET `EffectApplyAuraName2` = 163,
    `EffectMiscValue2`     = 127,
    `SpellDescription0`    = 'The Nathrezim watch over you. Damage taken is reduced by 1% and the critical strike damage of your spells is increased by 1% for each Soul Shard you carry.',
    `SpellToolTip0`        = 'Damage taken reduced by 1% and critical strike damage increased by 1% for each Soul Shard you carry.'
WHERE `ID` = 200507;

-- Sacrifice the Weak's own description referenced the old crit-chance wording.
UPDATE `alonecraft_spell_dbc`
SET `SpellDescription0` = 'Sacrifice your demon to a new master in the Twisting Nether. In return they grant you Nathrezim Foresight, reducing damage taken and increasing the critical strike damage of your spells by 1% for each Soul Shard you carry, up to 32.'
WHERE `ID` = 47220;
